            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (!existing.getId().equals(owner.getId())
                    && normalized.equals(normalizeTelephone(existing.getTelephone()))) {
                throw new DuplicateTelephoneException(normalized);
            }
        }
